/**
 * The cell's own read - the reloot's count across the lines.
 * The reloot book's own seat's count - the count this word prices
 * across the faces (the whole raw mass the lane prints - every line
 * rides, no exclusion the lane needs).
 *
 * @param {string[]|null} [lines] the face's own log lines
 * @returns {number} the reloot count (0 when the lines cannot prove
 *   a reloot line - the zero a lawful count)
 */
export function reloots (lines) {
  if (!Array.isArray(lines)) return 0
  let n = 0
  for (const l of lines) {
    if (typeof l === 'string' && RELOOT_RE.test(l)) n++
  }
  return n
}

/**
 * The fence - the fold's own image must prove itself before the word
 * rides. A fold that cannot prove itself prices nothing (the fence
 * law: the word never rides a lie). The zero count is lawful (the
 * smelt lane's own zero precedent). The fence never rejects extra
 * keys.
 *
 * @param {object|null} [e] the trend fold:
 *   { back: {reloots}, prev: {reloots}, cur: {reloots} }
 * @returns {boolean}
 */
export function relootTrendConsistent (e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return false
  const faceOk = (s) => {
    if (!s || typeof s !== 'object' || Array.isArray(s)) return false
    return Number.isInteger(s.reloots) && s.reloots >= 0
  }
  return faceOk(e.back) && faceOk(e.prev) && faceOk(e.cur)
}

/**
 * The word - one line, the reloot's own two-step shape. The honest
 * null when a step held (no direction - the family's own held law)
 * or the fold fails the fence.
 *
 * @param {object|null} [e] the trend fold
 *   { back: {reloots}, prev: {reloots}, cur: {reloots} }
 * @returns {string|null} the row byte, or null
 */
export function relootTrendRow (e) {
  if (!relootTrendConsistent(e)) return null
  const { back, prev, cur } = e
  const first = prev.reloots - back.reloots
  const second = cur.reloots - prev.reloots
  const arc = `${back.reloots} -> ${prev.reloots} (${first >= 0 ? '+' : ''}${first}) -> ${cur.reloots} (${second >= 0 ? '+' : ''}${second})`
  // a held step is no direction - the honest silence (the family's
  // own held law: the bars never invent)
  if (first === 0 || second === 0) return null
  if (first > 0 && second > 0) {
    return SWELL + arc + SWELL_TAIL
  }
  if (first < 0 && second < 0) {
    return FADE + arc + FADE_TAIL
  }
  return SWING + arc + SWING_TAIL
}
